    see: "LIKE dùng % cho một cụm bất kỳ và _ cho một ký tự. REGEXP hay RLIKE là biểu thức chính quy, tùy máy, không cùng một thư viện với LIKE. WHERE kênh LIKE '%tok' khớp tiktok. Nó cũng khớp một chữ rác kết thúc bằng tok. Không có mỏ neo thì đừng tưởng đó là cả ô.",
