    use: ["Bắt đầu bằng một cụm: 'tok%'. Kết thúc: '%tok'. Chứa: '%tok%'.", "Cần đúng chữ số hoặc một luật: dùng regex của đúng máy, và nói tên máy.", "Đừng regex một cột ngày. Dùng hàm ngày."],
